// План specs/pricebook.md 2.1 (кейс .qa/tests/pricebook/PB-04). Pre-Prod, preprod-ttp (TTP Test Locks), десктоп, EN.
// @writes @data: смета «QA-AUTO pb-pick #df9bec …» НЕ сохраняется; если появился черновик — Delete в конце.
// Предусловие: в Price Book TTP Test Locks есть хотя бы одна позиция.
import { test, expect } from '../../fixtures';
import { ROLE, itemRow, openNewEstimate, openPriceBook, pickFirstFromPriceBook, priceBookTotal, removeFromList, stamp } from './pricebook-helpers';

test.describe('Price Book — выбор позиции в документ (#df9bec)', () => {
  test('QA-AUTO: existing Price Book item is added to a new estimate via Select items → Add Selected #df9bec @desktop @writes @data', async ({ asUser }) => {
    test.setTimeout(120_000);
    const page = await asUser(ROLE);
    const title = `QA-AUTO pb-pick #df9bec ${stamp()}`;
    try {
      await openPriceBook(page);
      const before = await priceBookTotal(page);

      // Шаги 1–3: New Estimate → Price Book → первая позиция → Add Selected
      await openNewEstimate(page, title);
      const name = await pickFirstFromPriceBook(page, 'Add Selected');
      await expect(itemRow(page, name), `позиция «${name}» в Items сметы`).toHaveCount(1);

      // выбор не создаёт новую позицию в Price Book
      await openPriceBook(page);
      expect(await priceBookTotal(page), 'Total Items не изменилось').toBe(before);
    } finally {
      await removeFromList(page, '/assessments', title);
    }
  });
});
